async function main({ params, context }) {
  const resultStr = String(params.agentResult || '').trim();

  const parseScenes = (text) => {
    const parsed = JSON.parse(text);
    return { scenes: Array.isArray(parsed) ? parsed : [] };
  };

  const extractFirstJsonArray = (text) => {
    const start = text.indexOf('[');
    if (start === -1) return null;
    let depth = 0;
    let inString = false;
    let escaped = false;

    for (let i = start; i < text.length; i++) {
      const ch = text[i];
      if (inString) {
        if (escaped) {
          escaped = false;
        } else if (ch === '\\') {
          escaped = true;
        } else if (ch === '"') {
          inString = false;
        }
        continue;
      }
      if (ch === '"') {
        inString = true;
      } else if (ch === '[') {
        depth++;
      } else if (ch === ']') {
        depth--;
        if (depth === 0) return text.slice(start, i + 1);
      }
    }
    return null;
  };

  try {
    return parseScenes(resultStr);
  } catch (e) {
    const blockMatch = resultStr.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
    if (blockMatch) return parseScenes(blockMatch[1]);

    const firstArray = extractFirstJsonArray(resultStr);
    if (firstArray) return parseScenes(firstArray);

    throw new Error('无法解析JSON结果');
  }
}

